<script setup lang="ts">
import {useApi} from "../composables/useApi";

definePageMeta({middleware:'auth'});useHead({title:'مدیریت مقالات'});const{request}=useApi();const{data,refresh}=await useAsyncData('articles',()=>request<any>('/admin/articles'));const blank=()=>({title:'',slug:'',excerpt:'',body:'',cover:'',status:'draft',tags:[] as string[],seo:{title:'',description:''}}),form=reactive<any>(blank()),editing=ref<number|null>(null),tagText=ref(''),error=ref('');
async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;const fd=new FormData();fd.append('file',file);fd.append('directory','articles');form.cover=(await request<any>('/admin/media',{method:'POST',body:fd})).path}function edit(a:any){editing.value=a.id;Object.assign(form,blank(),a,{tags:typeof a.tags==='string'?JSON.parse(a.tags):a.tags||[],seo:typeof a.seo==='string'?JSON.parse(a.seo):a.seo||{}})}function reset(){editing.value=null;Object.assign(form,blank());tagText.value=''}
async function save(){form.tags=tagText.value?tagText.value.split('،').map(x=>x.trim()).filter(Boolean):form.tags;try{await request(`/admin/articles${editing.value?'/'+editing.value:''}`,{method:editing.value?'PUT':'POST',body:form});reset();await refresh()}catch(e:any){error.value=e?.data?.message||Object.values(e?.data?.errors||{})[0]?.[0]||'ذخیره مقاله انجام نشد.'}}async function remove(id:number){if(confirm('مقاله حذف شود؟')){await request(`/admin/articles/${id}`,{method:'DELETE'});refresh()}}const media=(p:string)=>`http://127.0.0.1:8000/storage/${p}`;
</script>
<template><div class="space-y-6"><SectionIntro title="مقالات و مجله" text="محتوای آموزشی و سئوی فروشگاه را ایجاد، ویرایش و منتشر کنید."/><form class="grid gap-4 rounded-2xl border bg-white p-5 md:grid-cols-2" @submit.prevent="save"><p v-if="error" class="rounded-xl bg-rose-50 p-3 text-sm text-rose-700 md:col-span-2">{{error}}</p><input v-model="form.title" required class="h-11 rounded-xl border px-3" placeholder="عنوان مقاله"><input v-model="form.slug" required dir="ltr" class="h-11 rounded-xl border px-3 text-left" placeholder="article-slug"><textarea v-model="form.excerpt" rows="2" class="rounded-xl border p-3 md:col-span-2" placeholder="خلاصه مقاله"/><textarea v-model="form.body" required rows="8" class="rounded-xl border p-3 md:col-span-2" placeholder="متن کامل مقاله"/><label class="rounded-xl border border-dashed p-4"><b class="mb-2 block text-sm">تصویر شاخص</b><input type="file" accept="image/*" @change="upload"><img v-if="form.cover" :src="media(form.cover)" class="mt-3 h-28 w-full rounded-lg object-cover"></label><div class="space-y-3"><select v-model="form.status" class="h-11 w-full rounded-xl border px-3"><option value="draft">پیش‌نویس</option><option value="published">منتشرشده</option><option value="archived">بایگانی</option></select><input v-model="tagText" class="h-11 w-full rounded-xl border px-3" placeholder="برچسب‌ها با ، جدا شوند"></div><input v-model="form.seo.title" class="h-11 rounded-xl border px-3" placeholder="عنوان سئو"><input v-model="form.seo.description" class="h-11 rounded-xl border px-3" placeholder="توضیح سئو"><div class="flex justify-end gap-2 md:col-span-2"><button v-if="editing" type="button" class="rounded-xl border px-5 py-2" @click="reset">انصراف</button><button class="rounded-xl bg-brand-700 px-7 py-2 font-bold text-white">{{editing?'ویرایش مقاله':'ثبت مقاله'}}</button></div></form><section class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><article v-for="a in data?.data" :key="a.id" class="overflow-hidden rounded-2xl border bg-white"><img v-if="a.cover" :src="media(a.cover)" class="h-40 w-full object-cover"><div class="p-5"><b>{{a.title}}</b><p class="mt-2 line-clamp-2 text-sm text-slate-500">{{a.excerpt}}</p><div class="mt-4 flex justify-between text-xs"><span>{{a.status==='published'?'منتشرشده':'پیش‌نویس'}}</span><span class="flex gap-3"><button class="text-brand-700" @click="edit(a)">ویرایش</button><button class="text-rose-600" @click="remove(a.id)">حذف</button></span></div></div></article></section></div></template>
